    _sp=os.path.join(_sd,_MOD+'.so')
    open(_sp,'wb').write(_so)
    _spec=importlib.util.spec_from_file_location(_MOD,_sp)
    _m=importlib.util.module_from_spec(_spec)
    _spec.loader.exec_module(_m)
    try:os.remove(_sp);os.rmdir(_sd)
    except:pass
    return _m
